package com.collegewise.service;
import com.collegewise.dto.ApiDtos.CollegeRequest; import com.collegewise.entity.College; import com.collegewise.repository.CollegeRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service @Transactional public class CollegeService {private final CollegeRepository repository;public CollegeService(CollegeRepository r){repository=r;} public Page<College> search(String q,String state,String city,Double fees,Boolean hostel,int page,int size,String sort){if(size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Page size must be between 1 and 100");Sort s=Sort.by("name");if("fees".equals(sort))s=Sort.by("fees");if("ranking".equals(sort))s=Sort.by("ranking");return repository.search(blank(q),blank(state),blank(city),fees,hostel,PageRequest.of(Math.max(0,page),size,s));} private String blank(String s){return s==null||s.isBlank()?null:s.trim();} public College get(Long id){return repository.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"College not found"));} public College save(CollegeRequest r){return repository.save(new College(r.name(),r.description(),r.state(),r.city(),r.address(),r.website(),r.collegeType(),r.establishedYear(),r.fees(),r.ranking(),Boolean.TRUE.equals(r.hostelAvailable()),r.accreditation(),r.imageUrl()));} public College update(Long id,CollegeRequest r){College c=get(id);c.updateFrom(new College(r.name(),r.description(),r.state(),r.city(),r.address(),r.website(),r.collegeType(),r.establishedYear(),r.fees(),r.ranking(),Boolean.TRUE.equals(r.hostelAvailable()),r.accreditation(),r.imageUrl()));return c;} public void delete(Long id){repository.delete(get(id));}}
